  ('00000000-0000-0000-0000-000000000103', '00000000-0000-0000-0000-000000000001', 1, 1, 1, DATE '2026-02-24', 'Pressão e recuperação de bola'),
  ('00000000-0000-0000-0000-000000000104', '00000000-0000-0000-0000-000000000001', 2, 2, 2, DATE '2026-02-28', 'Amistoso preparatório'),
  ('00000000-0000-0000-0000-000000000105', '00000000-0000-0000-0000-000000000001', 1, 1, 2, DATE '2026-03-07', 'Transição ofensiva'),
  ('00000000-0000-0000-0000-000000000106', '00000000-0000-0000-0000-000000000001', 1, 1, 1, DATE '2026-03-12', 'Bola parada e finalização'),
  ('00000000-0000-0000-0000-000000000107', '00000000-0000-0000-0000-000000000001', 2, 2, 2, DATE '2026-03-17', 'Jogo-treino'),
  ('00000000-0000-0000-0000-000000000108', '00000000-0000-0000-0000-000000000001', 1, 1, 2, DATE '2026-03-24', 'Ajustes coletivos')
ON CONFLICT (id) DO NOTHING;

WITH performance (sessao_id, jogador_id, positivas, negativas) AS (
  VALUES
    ('00000000-0000-0000-0000-000000000103'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 5, 3),
    ('00000000-0000-0000-0000-000000000103'::uuid, '00000000-0000-0000-0000-000000000202'::uuid, 4, 4),
    ('00000000-0000-0000-0000-000000000103'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 6, 2),
    ('00000000-0000-0000-0000-000000000103'::uuid, '00000000-0000-0000-0000-000000000204'::uuid, 5, 2),
    ('00000000-0000-0000-0000-000000000103'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 4, 3),
    ('00000000-0000-0000-0000-000000000104'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 6, 2),
    ('00000000-0000-0000-0000-000000000104'::uuid, '00000000-0000-0000-0000-000000000202'::uuid, 5, 3),
    ('00000000-0000-0000-0000-000000000104'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 5, 4),
    ('00000000-0000-0000-0000-000000000104'::uuid, '00000000-0000-0000-0000-000000000204'::uuid, 6, 2),
    ('00000000-0000-0000-0000-000000000104'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 5, 3),
    ('00000000-0000-0000-0000-000000000105'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 6, 2),
    ('00000000-0000-0000-0000-000000000105'::uuid, '00000000-0000-0000-0000-000000000202'::uuid, 6, 3),
    ('00000000-0000-0000-0000-000000000105'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000105'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 5, 4),
    ('00000000-0000-0000-0000-000000000106'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000106'::uuid, '00000000-0000-0000-0000-000000000202'::uuid, 6, 2),
    ('00000000-0000-0000-0000-000000000106'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 6, 3),
    ('00000000-0000-0000-0000-000000000106'::uuid, '00000000-0000-0000-0000-000000000204'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000106'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 6, 3),
    ('00000000-0000-0000-0000-000000000107'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 6, 3),
    ('00000000-0000-0000-0000-000000000107'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000107'::uuid, '00000000-0000-0000-0000-000000000204'::uuid, 6, 3),
    ('00000000-0000-0000-0000-000000000107'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000108'::uuid, '00000000-0000-0000-0000-000000000201'::uuid, 8, 1),
    ('00000000-0000-0000-0000-000000000108'::uuid, '00000000-0000-0000-0000-000000000202'::uuid, 7, 2),
    ('00000000-0000-0000-0000-000000000108'::uuid, '00000000-0000-0000-0000-000000000203'::uuid, 8, 2),
    ('00000000-0000-0000-0000-000000000108'::uuid, '00000000-0000-0000-0000-000000000204'::uuid, 7, 1),
    ('00000000-0000-0000-0000-000000000108'::uuid, '00000000-0000-0000-0000-000000000205'::uuid, 7, 2)
), numbered_actions AS (
  SELECT
    performance.*,
    generate_series(1, positivas + negativas) AS ordem
  FROM performance
)
INSERT INTO acoes_taggeadas (
  id,
  sessao_id,
  acao_catalogo_id,
  jogador_id,
  timestamp_segundos
)
SELECT
  md5(format('comparison-action-%s-%s-%s', sessao_id, jogador_id, ordem))::uuid,
  sessao_id,
  CASE
    WHEN ordem <= positivas THEN
      (ARRAY[
        '00000000-0000-0000-0000-000000000411'::uuid,
        '00000000-0000-0000-0000-000000000412'::uuid,
        '00000000-0000-0000-0000-000000000418'::uuid,
        '00000000-0000-0000-0000-000000000419'::uuid,
        '00000000-0000-0000-0000-000000000413'::uuid
      ])[1 + ((ordem - 1) % 5)]
    ELSE
      (ARRAY[
        '00000000-0000-0000-0000-000000000415'::uuid,
        '00000000-0000-0000-0000-000000000417'::uuid,
        '00000000-0000-0000-0000-000000000406'::uuid
      ])[1 + ((ordem - positivas - 1) % 3)]
  END,
  jogador_id,
  ordem * 42
FROM numbered_actions
ON CONFLICT (id) DO NOTHING;

COMMIT;
